    if (word === null) return
    const expanded = expandBraces(word)
    if (redirect === 'write' || (redirect === 'dup' && !/^(?:\d+-?|-)$/.test(word))) writes.push(...expanded)
    else if (redirect !== 'read' && redirect !== 'dup') words.push(...expanded)
    redirect = null
    word = null
  }
