    endWord()
    redirect = null
    if (words.length || writes.length) {
      const w = unwrap(words)
      const name = base(w[0])
      const args = w.slice(1)
      const xargs = words.slice(0, words.length - w.length).some(x => base(x) === 'xargs')
      out.push(xargs ? { name, args, writes, xargs } : { name, args, writes })
      if (SHELLS.has(name)) {
