        if (c >= 0 && args[c + 1] !== undefined) nested(/** @type {string} */ (args[c + 1]))
      } else if (name === 'eval') nested(args.join(' '))
    }
    words = []
    writes = []
  }

  const n = src.length
  let i = 0
  while (i < n) {
    const c = /** @type {string} */ (src[i])
    if (c === '\n') {
      const pending = heredocs
      endCommand()
      i++
      for (const h of pending) {
        /** @type {string[]} */
        const body = []
        while (i < n) {
