        redirect = src[i + 1] === '>' ? 'write' : 'read'
        i += src[i + 1] === '>' || src[i + 1] === '&' ? 2 : 1
      } else {
        let k = i + 1
        if (src[k] === '>' || src[k] === '|') k++
        redirect = src[k] === '&' ? 'dup' : 'write'
        if (src[k] === '&') k++
        i = k
      }
    } else {
      // `${...}` is a parameter, not a brace expansion.
      append(c === '{' && !(word ?? '').endsWith('$') ? LB : c === ',' ? CM : c === '}' ? RB : c)
      i++
    }
  }
  endCommand()
  return out
}

